// Normalize Gainsight usage into a 0-100 sub-score against the account's own 28d baseline.
// This catches drops that absolute thresholds miss (a 35% drop matters whether the account is at 1k or 100k events/day).
const account = $('Batch Accounts (25/group)').item.json;
const usagePayload = $json;
const baseline = Number(account.baseline_usage_28d) || 0;
const current = Number(usagePayload?.totals?.eventsLast28d) || 0;
const dau = Number(usagePayload?.totals?.distinctUsersLast28d) || 0;
const minutes = Number(usagePayload?.totals?.minutesInProductLast28d) || 0;

let ratio;
if (baseline === 0) {
  ratio = current > 0 ? 1 : 0;
} else {
  ratio = current / baseline;
}

// Map ratio to 0-100. Above baseline caps at 100 (we don't reward usage spikes — they can mean a fire drill).
// Below baseline drops linearly to 0 at ratio=0.5 (50% of baseline = score 0). Below 0.5 stays at 0.
let usageScore;
if (ratio >= 1) usageScore = 100;
else if (ratio <= 0.5) usageScore = 0;
else usageScore = Math.round((ratio - 0.5) * 200);

// Penalty if distinct users drop below 3 — single-user dependency is a churn risk regardless of event volume.
if (dau < 3) usageScore = Math.min(usageScore, 40);

return [{
  json: {
    account_id: account.account_id,
    account_name: account.account_name,
    sub_usage: {
      score: usageScore,
      ratio_vs_baseline: Number(ratio.toFixed(2)),
      events_28d: current,
      distinct_users_28d: dau,
      minutes_in_product_28d: minutes,
    },
    _account: account,
  }
}];

// Score CSM/support activity from HubSpot engagements.
// Recency-weighted: a meeting yesterday is worth more than one 60 days ago.
const account = $('Batch Accounts (25/group)').item.json;
const payload = $json;
const engagements = Array.isArray(payload?.results) ? payload.results : [];
const now = Date.now();
const halfLifeDays = 21;

let weightedSum = 0;
let meetingCount = 0;
let emailCount = 0;
let lastMeetingAt = null;

for (const e of engagements) {
  const ts = e?.properties?.hs_timestamp ? Date.parse(e.properties.hs_timestamp) : null;
  if (!ts) continue;
  const ageDays = (now - ts) / 86400000;
  if (ageDays > 90) continue;
  const decay = Math.pow(0.5, ageDays / halfLifeDays);
  const type = (e?.properties?.hs_engagement_type || '').toUpperCase();
  let weight = 0;
  if (type === 'MEETING') { weight = 5; meetingCount += 1; if (!lastMeetingAt || ts > lastMeetingAt) lastMeetingAt = ts; }
  else if (type === 'CALL') { weight = 4; }
  else if (type === 'EMAIL') { weight = 1; emailCount += 1; }
  else if (type === 'NOTE') { weight = 0.5; }
  weightedSum += weight * decay;
}

// Map weighted sum to 0-100. 30+ = saturated relationship, 0 = silent.
let activityScore = Math.min(100, Math.round((weightedSum / 30) * 100));

// Hard floor: zero meetings in 60 days drops the activity score to 25 max.
if (!lastMeetingAt || (now - lastMeetingAt) / 86400000 > 60) {
  activityScore = Math.min(activityScore, 25);
}

return [{
  json: {
    account_id: account.account_id,
    account_name: account.account_name,
    sub_activity: {
      score: activityScore,
      meetings_90d: meetingCount,
      emails_90d: emailCount,
      last_meeting_at: lastMeetingAt ? new Date(lastMeetingAt).toISOString() : null,
      weighted_sum: Number(weightedSum.toFixed(2)),
    },
    _account: account,
  }
}];

