// Normalize Claude sentiment output to a 0-100 sub-score with a confidence floor.
const account = $('Batch Accounts (25/group)').item.json;
const raw = $json?.content?.[0]?.text || '{}';
let parsed;
try { parsed = JSON.parse(raw); } catch (e) { parsed = { sentiment: 0, signals: [], confidence: 0 }; }

const sentiment = typeof parsed.sentiment === 'number' ? parsed.sentiment : 0;
const confidence = typeof parsed.confidence === 'number' ? parsed.confidence : 0;
const signals = Array.isArray(parsed.signals) ? parsed.signals.slice(0, 4) : [];

// Map -1..+1 → 0..100. Confidence below 0.4 collapses to 50 (neutral) so we don't act on guesses.
let sentimentScore;
if (confidence < 0.4) {
  sentimentScore = 50;
} else {
  sentimentScore = Math.round(((sentiment + 1) / 2) * 100);
}

return [{
  json: {
    account_id: account.account_id,
    account_name: account.account_name,
    sub_sentiment: {
      score: sentimentScore,
      raw_sentiment: sentiment,
      confidence,
      signals,
    },
    _account: account,
  }
}];

// Composite = weighted sum of three sub-scores. Compare against last score for delta + drivers.
const row = $json;
const account = row._account || {};

const wU = Number(account.weight_usage ?? 0.5);
const wA = Number(account.weight_activity ?? 0.3);
const wS = Number(account.weight_sentiment ?? 0.2);
const totalW = wU + wA + wS;

const sU = row.sub_usage?.score ?? 50;
const sA = row.sub_activity?.score ?? 50;
const sS = row.sub_sentiment?.score ?? 50;

const composite = Math.round((wU * sU + wA * sA + wS * sS) / totalW);

const band = composite >= 75 ? 'green' : composite >= 50 ? 'yellow' : 'red';

return [{
  json: {
    account_id: account.account_id,
    account_name: account.account_name,
    gainsight_company_id: account.gainsight_company_id,
    composite,
    band,
    sub_usage: row.sub_usage,
    sub_activity: row.sub_activity,
    sub_sentiment: row.sub_sentiment,
    weights: { usage: wU, activity: wA, sentiment: wS },
    scored_at: new Date().toISOString(),
  }
}];

