// Compose the final write-back payload. Use Claude's sentence if available; otherwise a deterministic fallback.
const composite = $('Compute Composite').item.json;
const prev = $('Lookup Previous Score').item.json || {};
const whyText = $json?.content?.[0]?.text;

const delta = composite.composite - (prev.prev_composite ?? composite.composite);
const fallback = `Composite ${delta >= 0 ? 'up' : 'down'} ${Math.abs(delta)} pts (usage ${composite.sub_usage.score}, activity ${composite.sub_activity.score}, sentiment ${composite.sub_sentiment.score}).`;

return [{
  json: {
    ...composite,
    delta,
    why_changed: (typeof whyText === 'string' && whyText.trim().length > 0) ? whyText.trim() : fallback,
  }
}];
